/**
 * 경영: money in (매출 청구, 수금, 미수금), money out (매입, 경비, 지급), and
 * the ledger they post to (분개, 시산표, 프로젝트 손익, CSV).
 *
 * Postings are not made here: the database writes the journal entry for an
 * invoice, a receipt, an approved expense, a confirmed purchase and a
 * payment in the same transaction as the row itself (migration 0006), and
 * refuses an entry that does not balance or a change to one that exists.
 */
import { Router } from '../http/router.js'
import { json } from '../http/respond.js'
import { AppError, forbidden, invalid, notFound } from '../errors.js'
import { parse, parseOne, v } from '../util/validate.js'
import { can, covers, member, requirePerm } from '../auth/tenant.js'
import { approvalOf, submitForApproval } from '../domain/subjects.js'
import { assertVisible, idParam, READ, searchTerm, sent, today, vatOf, W, WRITE } from './w.js'
import type { Ctx } from '../http/types.js'

const STEP_INPUT = v.object(
  {
    seq: v.int({ min: 1, max: 20, label: '순서' }),
    kind: v.oneOf(['approve', 'agree', 'reference'] as const, { label: '종류' }),
    member_id: v.uuid({ label: '결재자' }),
    final_allowed: v.optional(v.bool({ label: '전결 허용' }), false),
  },
  { label: '결재 단계' },
)
const PAY_METHODS = ['personal_card', 'corporate_card', 'cash', 'transfer'] as const
const PAY_LABEL: Record<(typeof PAY_METHODS)[number], string> = { personal_card: '개인카드', corporate_card: '법인카드', cash: '현금', transfer: '계좌이체' }

export function financeRoutes(): Router {
  const router = new Router()

  // ------------------------------------------------------------ invoices --

  router.get(
    `${W}/invoices`,
    async (ctx) => {
      const m = member(ctx)
      const status = ctx.query.get('status') ?? ''
      const overdue = ctx.query.get('overdue') === '1'
      const open = ctx.query.get('open') === '1'
      const customer = ctx.query.get('customer') ?? ''
      const q = searchTerm(ctx)
      const rows = await ctx.sql`
        SELECT i.id, i.invoice_no, i.title, i.issue_date, i.due_date, i.supply_amount, i.vat_amount, i.total_amount, i.paid_amount, i.status,
               i.customer_id, c.name AS customer_name, i.project_id, p.name AS project_name, i.contract_id,
               (i.status IN ('issued','partial') AND i.due_date < (now() AT TIME ZONE 'Asia/Seoul')::date) AS overdue
        FROM biz.invoices i JOIN biz.customers c ON c.id = i.customer_id LEFT JOIN biz.projects p ON p.id = i.project_id
        WHERE i.company_id = ${m.companyId} AND (${status} = '' OR i.status = ${status})
          AND (${!overdue} OR (i.status IN ('issued','partial') AND i.due_date < (now() AT TIME ZONE 'Asia/Seoul')::date))
          AND (${!open} OR i.status IN ('issued','partial'))
          AND (${customer} = '' OR i.customer_id::text = ${customer})
          AND (${q} = '' OR i.title ILIKE ${'%' + q + '%'} OR i.invoice_no ILIKE ${'%' + q + '%'} OR c.name ILIKE ${'%' + q + '%'})
        ORDER BY i.issue_date DESC, i.created_at DESC LIMIT 500`
      return { items: rows, can_create: can(m, 'sales.write') }
    },
    { ...READ, summary: '매출 청구 목록' },
  )

  router.post(
    `${W}/invoices`,
    async (ctx) => {
      const m = member(ctx)
      if (!can(m, 'sales.write')) throw forbidden('매출을 청구할 권한이 없습니다.')
      const input = parse(
        {
          customer_id: v.uuid({ label: '거래처' }),
          contract_id: v.optional(v.uuid({ label: '계약' })),
          project_id: v.optional(v.uuid({ label: '프로젝트' })),
          title: v.string({ min: 1, max: 120, label: '청구 내용' }),
          issue_date: v.optional(v.day({ label: '청구일' })),
          due_date: v.day({ label: '입금 기한' }),
          supply_amount: v.money({ label: '공급가', min: 1 }),
          vat_amount: v.optional(v.money({ label: '부가세' })),
          revenue_account: v.optional(v.oneOf(['4010', '4020'] as const, { label: '매출 계정' }), '4020'),
          memo: v.optional(v.text({ min: 0, max: 2000, label: '메모' }), ''),
        },
        await ctx.body(),
      )
      const issue = input.issue_date ?? today()
      if (input.due_date < issue) throw invalid({ due_date: '입금 기한은 청구일보다 같거나 늦어야 합니다.' })
      await assertVisible(ctx.sql, [
        { table: 'customers', id: input.customer_id, field: 'customer_id' },
        { table: 'contracts', id: input.contract_id, field: 'contract_id' },
        { table: 'projects', id: input.project_id, field: 'project_id' },
      ])
      if (input.contract_id) {
        // Billing follows the contract's life: started (or finished), never before.
        const ct = await ctx.sql<{ status: string; customer_id: string }[]>`SELECT status, customer_id FROM biz.contracts WHERE id = ${input.contract_id}`
        if (!['active', 'completed'].includes(ct[0]!.status)) throw new AppError('state_conflict', '계약을 시작한 뒤에 그 계약으로 청구할 수 있습니다.')
        if (ct[0]!.customer_id !== input.customer_id) throw invalid({ contract_id: '이 거래처의 계약이 아닙니다.' })
      }
      const rows = await ctx.sql<{ id: string; invoice_no: string }[]>`
        INSERT INTO biz.invoices (company_id, invoice_no, customer_id, contract_id, project_id, title, issue_date, due_date, supply_amount, vat_amount,
                                  total_amount, revenue_account, owner_id, department_id, memo)
        VALUES (${m.companyId}, NULL, ${input.customer_id}, ${input.contract_id ?? null}, ${input.project_id ?? null}, ${input.title}, ${issue}, ${input.due_date},
                ${input.supply_amount}, ${input.vat_amount ?? vatOf(input.supply_amount)}, 0, ${input.revenue_account ?? '4020'}, ${m.memberId}, ${m.departmentId}, ${input.memo ?? ''})
        RETURNING id, invoice_no`
      await ctx.audit({ action: 'finance.invoice_issued', targetType: 'invoice', targetId: rows[0]!.id, after: { amount: input.supply_amount } })
      return json({ id: rows[0]!.id, invoice_no: rows[0]!.invoice_no }, { status: 201 })
    },
    { ...WRITE, summary: '매출 청구' },
  )

  router.get(
    `${W}/invoices/:id`,
    async (ctx) => {
      const m = member(ctx)
      const id = idParam(ctx, 'id', '청구')
      const rows = await ctx.sql`
        SELECT i.*, c.name AS customer_name, p.name AS project_name, ct.contract_no, o.display_name AS owner_name
        FROM biz.invoices i JOIN biz.customers c ON c.id = i.customer_id LEFT JOIN biz.projects p ON p.id = i.project_id
        LEFT JOIN biz.contracts ct ON ct.id = i.contract_id LEFT JOIN biz.members o ON o.id = i.owner_id
        WHERE i.id = ${id} AND i.company_id = ${m.companyId}`
      const inv = rows[0]
      if (!inv) throw notFound('청구를 찾을 수 없거나 볼 권한이 없습니다.')
      const receipts = await ctx.sql`
        SELECT r.id, r.receipt_no, r.amount, r.received_on, r.method, r.memo, x.display_name AS created_by_name, r.created_at,
               rc.created_at AS cancelled_at, rc.reason AS cancel_reason
        FROM biz.receipts r LEFT JOIN biz.members x ON x.id = r.created_by LEFT JOIN biz.receipt_cancellations rc ON rc.receipt_id = r.id
        WHERE r.invoice_id = ${id} ORDER BY r.received_on, r.created_at`
      const editable = covers(m, 'sales.write', inv.owner_id as string | null, inv.department_id as string | null)
      return {
        ...inv, receipts,
        can: {
          receive: editable && ['issued', 'partial'].includes(String(inv.status)),
          void: editable && inv.status === 'issued' && Number(inv.paid_amount) === 0,
          cancel_receipt: editable && ['partial', 'paid'].includes(String(inv.status)),
        },
      }
    },
    { ...READ, summary: '청구 보기' },
  )

  router.post(
    `${W}/invoices/:id/receipts`,
    async (ctx) => {
      const m = member(ctx)
      const id = idParam(ctx, 'id', '청구')
      const input = parse(
        {
          amount: v.money({ label: '수금액', min: 1 }),
          received_on: v.optional(v.day({ label: '입금일' })),
          method: v.optional(v.oneOf(['transfer', 'card', 'cash', 'other'] as const, { label: '방법' }), 'transfer'),
          memo: v.optional(v.string({ min: 0, max: 300, label: '메모' }), ''),
        },
        await ctx.body(),
      )
      const rows = await ctx.sql<{ id: string; receipt_no: string }[]>`
        INSERT INTO biz.receipts (company_id, invoice_id, amount, received_on, method, memo, created_by)
        VALUES (${m.companyId}, ${id}, ${input.amount}, ${input.received_on ?? today()}, ${input.method ?? 'transfer'}, ${input.memo ?? ''}, ${m.memberId})
        RETURNING id, receipt_no`
      await ctx.audit({ action: 'finance.receipt', targetType: 'invoice', targetId: id, after: { amount: input.amount } })
      return json({ id: rows[0]!.id, receipt_no: rows[0]!.receipt_no }, { status: 201 })
    },
    { ...WRITE, summary: '수금 등록' },
  )

  router.post(
    `${W}/invoices/:id/receipts/:receiptId/cancel`,
    async (ctx) => {
      const m = member(ctx)
      const id = idParam(ctx, 'id', '청구')
      const receiptId = idParam(ctx, 'receiptId', '수금')
      const input = parse({ reason: v.string({ min: 2, max: 200, label: '취소 사유' }) }, await ctx.body())
      const found = await ctx.sql`SELECT 1 FROM biz.receipts WHERE id = ${receiptId} AND invoice_id = ${id} AND company_id = ${m.companyId}`
      if (!found[0]) throw notFound('수금을 찾을 수 없거나 볼 권한이 없습니다.')
      const rows = await ctx.sql`
        INSERT INTO biz.receipt_cancellations (company_id, receipt_id, reason, created_by)
        VALUES (${m.companyId}, ${receiptId}, ${input.reason}, ${m.memberId})
        ON CONFLICT (receipt_id) DO NOTHING RETURNING id`
      if (!rows[0]) throw new AppError('conflict', '이미 취소한 수금입니다.')
      await ctx.audit({ action: 'finance.receipt_cancelled', targetType: 'invoice', targetId: id, reason: input.reason, after: { receipt: receiptId } })
      return { ok: true }
    },
    { ...WRITE, summary: '수금 취소(역분개)' },
  )

  router.post(
    `${W}/invoices/:id/void`,
    async (ctx) => {
      const m = member(ctx)
      const id = idParam(ctx, 'id', '청구')
      const input = parse({ reason: v.string({ min: 2, max: 200, label: '취소 사유' }) }, await ctx.body())
      const rows = await ctx.sql`
        UPDATE biz.invoices SET status = 'void', void_reason = ${input.reason} WHERE id = ${id} AND company_id = ${m.companyId} RETURNING id`
      if (!rows[0]) throw notFound('청구를 찾을 수 없거나 취소할 권한이 없습니다.')
      await ctx.audit({ action: 'finance.invoice_voided', targetType: 'invoice', targetId: id, reason: input.reason })
      return { ok: true }
    },
    { ...WRITE, summary: '청구 취소(역분개)' },
  )

  router.get(
    `${W}/receivables`,
    async (ctx) => {
      const m = member(ctx)
      const min = Number(ctx.query.get('min')) || 0
      const rows = await ctx.sql<{ customer_id: string; customer_name: string; invoices: number; outstanding: number; overdue: number; oldest_due: string | null }[]>`
        SELECT c.id AS customer_id, c.name AS customer_name, count(*)::int AS invoices,
               sum(i.total_amount - i.paid_amount) AS outstanding,
               sum(CASE WHEN i.due_date < (now() AT TIME ZONE 'Asia/Seoul')::date THEN i.total_amount - i.paid_amount ELSE 0 END) AS overdue,
               min(i.due_date)::text AS oldest_due
        FROM biz.invoices i JOIN biz.customers c ON c.id = i.customer_id
        WHERE i.company_id = ${m.companyId} AND i.status IN ('issued','partial')
        GROUP BY c.id, c.name
        HAVING sum(i.total_amount - i.paid_amount) >= ${min}
        ORDER BY sum(i.total_amount - i.paid_amount) DESC`
      const total = rows.reduce((s, r) => s + Number(r.outstanding), 0)
      const overdue = rows.reduce((s, r) => s + Number(r.overdue), 0)
      return { items: rows, total, overdue }
    },
    { ...READ, summary: '미수금(거래처별)' },
  )

  // ------------------------------------------------------------ expenses --

  router.get(
    `${W}/expense-categories`,
    async (ctx) => {
      const m = member(ctx)
      const rows = await ctx.sql`
        SELECT code, name FROM biz.ledger_accounts WHERE company_id = ${m.companyId} AND type = 'expense' AND expense_category AND active ORDER BY code`
      return { items: rows }
    },
    { ...READ, summary: '경비 분류(비용 계정)' },
  )

  router.get(
    `${W}/expenses`,
    async (ctx) => {
      const m = member(ctx)
      const view = ctx.query.get('view') ?? 'mine'
      const status = ctx.query.get('status') ?? ''
      const rows = await ctx.sql`
        SELECT e.id, e.expense_no, e.title, e.category, a.name AS category_name, e.spent_on, e.supply_amount, e.vat_amount, e.total_amount,
               e.pay_method, e.status, e.member_id, x.display_name AS member_name, d.name AS department_name, e.project_id, p.name AS project_name,
               e.created_at
        FROM biz.expenses e
/**
 * 원장: the double-entry ledger every money row posts to.
 *
 *   분개장       entries in a period, each with its debit/credit lines
 *   시산표       per-account debit, credit and balance for the period, with
 *                the period's income (수익 - 비용)
 *   프로젝트 손익 revenue and cost booked against each project, all time by
 *                default (budget use is lifetime) or for the period
 *   계정과목     the chart of accounts: add, rename, turn off and on
 *
 * Entries are never changed: a mistake is answered with a reversal (역분개),
 * and anything the business rows do not post is entered by hand (수동 분개),
 * which is refused until debit and credit balance.
 */
import { ActionIcon, Button, Checkbox, Group, Modal, SegmentedControl, Select, SimpleGrid, Stack, Switch, Tabs, Text, TextInput } from '@mantine/core'
import { useMediaQuery } from '@mantine/hooks'
import { IconDownload, IconPlus, IconTrash } from '@tabler/icons-react'
import { useState, type ReactNode } from 'react'
import { useSearchParams } from 'react-router-dom'
import { ApiError, api, qs } from '../../../api/client'
import { EmptyState, ErrorState, FullLoader, Notice, PageHead, StatusBadge, Tag, fieldError, toast, useTitle } from '../../../components/ui'
import { PROJECT_STATUS, addDays, date, krw, today } from '../../../lib/format'
import { useAsync, type AsyncState } from '../../../state/useAsync'
import { useWs } from '../../../state/workspace'
import {
  ACCOUNT_TYPE,
  ACCOUNT_TYPES,
  AccountName,
  Busy,
  ConfirmModal,
  Figures,
  FormProblem,
  InLink,
  JOURNAL_KIND,
  MoneyInput,
  NoAccess,
  NumCell,
  PostingPreview,
  Toolbar,
  amt,
  isDay,
  monthOf,
  type Amount,
} from './parts'

interface AccountRow {
  code: string
  name: string
  type: string
  system: boolean
  active: boolean
  expense_category: boolean
}

interface AccountsResponse {
  items: AccountRow[]
  can_edit: boolean
}

interface JournalLine {
  entry_id: string
  line_no: number
  account_code: string
  account_name: string
  debit: number
  credit: number
  memo: string
  project_name: string | null
  customer_name: string | null
}

interface JournalEntry {
  id: string
  entry_no: string
  entry_date: string
  memo: string
  reversal_of: string | null
  kind: string
  source_type: string
  source_id: string | null
  reversed: boolean
  created_by_name: string | null
  lines: JournalLine[]
}

interface JournalResponse {
  from: string
  to: string
  items: JournalEntry[]
  can_post: boolean
}

interface TrialRow {
  code: string
  name: string
  type: string
  debit: number
  credit: number
  balance: number
}

interface TrialResponse {
  from: string
  to: string
  items: TrialRow[]
  totals: { debit: number; credit: number }
  balanced: boolean
  income: { revenue: number; expense: number; profit: number }
}

interface PlResponse {
  /** null: since the start / until now. */
  from: string | null
  to: string | null
  items: PlRow[]
}

interface PlRow {
  project_id: string
  code: string
  name: string
  status: string
  budget: number | null
  revenue: number
  cost: number
  profit: number
  margin: number | null
}

interface Period {
  from: string
  to: string
}

type Tab = 'journal' | 'trial' | 'pl' | 'accounts'
const TABS: readonly Tab[] = ['journal', 'trial', 'pl', 'accounts']

/** Where an automatic entry came from, when that has a page. */
const SOURCE_PAGE: Record<string, { path: string; label: string }> = {
  invoice: { path: '/finance/invoices', label: '청구 보기' },
  expense: { path: '/finance/expenses', label: '경비 보기' },
  purchase: { path: '/finance/purchases', label: '매입 보기' },
}

/** Asset and expense accounts grow on the debit side; the rest on the credit side. */
function debitNormal(type: string | undefined): boolean {
  return type === 'asset' || type === 'expense'
}

function accountOptions(items: AccountRow[]) {
  return ACCOUNT_TYPES.map((t) => ({
    group: ACCOUNT_TYPE[t] ?? t,
    items: items.filter((a) => a.type === t).map((a) => ({ value: a.code, label: `${a.code} ${a.name}${a.active ? '' : ' (사용 안 함)'}` })),
  })).filter((g) => g.items.length > 0)
}

export function Ledger(): ReactNode {
  const ws = useWs()
  useTitle('원장')
  if (!ws.can('ledger.read', 'company')) return <NoAccess message="원장을 볼 권한(원장 보기)이 없습니다." />
  return <LedgerBody />
}

function LedgerBody(): ReactNode {
  const ws = useWs()
  const [params] = useSearchParams()
  const [tab, setTab] = useState<Tab>(() => {
    const t = params.get('tab')
    return TABS.find((x) => x === t) ?? 'journal'
  })
  const thisMonth = monthOf(today())
  const [from, setFrom] = useState(thisMonth.from)
  const [to, setTo] = useState(thisMonth.to)
  const [account, setAccount] = useState<string | null>(null)
  // 프로젝트 손익 is all time unless asked otherwise: budgets are lifetime.
  const [plScope, setPlScope] = useState<'all' | 'period'>('all')
  // Bumped after a manual entry, so the open tab reads again.
  const [version, setVersion] = useState(0)
  const [manual, setManual] = useState(false)
  const accounts = useAsync((signal) => api.get<AccountsResponse>(ws.apiPath('/ledger/accounts'), { signal }), [ws.code])
  const canPost = ws.can('ledger.write', 'company')

  const periodError = !isDay(from) || !isDay(to) ? '기간의 시작과 끝을 입력해 주세요.' : to < from ? '끝은 시작보다 같거나 늦어야 합니다.' : null
  const period: Period | null = periodError ? null : { from, to }
  const dated = tab === 'journal' || tab === 'trial' || (tab === 'pl' && plScope === 'period')
  const year = today().slice(0, 4)
  const presets: { label: string; range: Period }[] = [
    { label: '이번 달', range: thisMonth },
    { label: '지난 달', range: monthOf(addDays(thisMonth.from, -1)) },
    { label: '올해', range: { from: `${year}-01-01`, to: `${year}-12-31` } },
  ]

  return (
    <>
      <PageHead
        eyebrow="경영"
        title="원장"
        actions={
          <>
            {period ? (
              <Button component="a" href={ws.apiPath(`/ledger/export.csv${qs({ from: period.from, to: period.to })}`)} download variant="default" leftSection={<IconDownload size={16} />}>
                CSV 내려받기
              </Button>
            ) : null}
            {canPost ? (
              <Button leftSection={<IconPlus size={16} />} onClick={() => setManual(true)}>
                수동 분개
              </Button>
            ) : null}
          </>
        }
      >
        청구·수금·경비·매입·지급은 복식부기 전표로 자동 기록됩니다. 기록된 전표는 고치거나 지울 수 없고, 바로잡을 때는 역분개 전표를 더합니다. CSV는 위 기간의
        분개장입니다.
      </PageHead>

      <Tabs value={tab} onChange={(v) => setTab(TABS.find((x) => x === v) ?? 'journal')} keepMounted={false}>
        <Tabs.List mb="md">
          <Tabs.Tab value="journal">분개장</Tabs.Tab>
          <Tabs.Tab value="trial">시산표</Tabs.Tab>
          <Tabs.Tab value="pl">프로젝트 손익</Tabs.Tab>
          <Tabs.Tab value="accounts">계정과목</Tabs.Tab>
        </Tabs.List>

        {tab === 'pl' || dated ? (
          <Toolbar>
            {tab === 'pl' ? (
              <SegmentedControl
                aria-label="프로젝트 손익 기간"
                value={plScope}
                onChange={(v) => setPlScope(v === 'period' ? 'period' : 'all')}
                data={[
                  { value: 'all', label: '전체 기간' },
                  { value: 'period', label: '기간 지정' },
                ]}
              />
            ) : null}
            {dated ? (
              <>
                <div style={{ display: 'flex', alignItems: 'center', gap: 6, flex: '1 1 300px', maxWidth: 380 }}>
                  <TextInput type="date" aria-label="기간 시작" value={from} onChange={(e) => setFrom(e.currentTarget.value)} error={!isDay(from)} style={{ flex: 1, minWidth: 0 }} />
                  <span aria-hidden>~</span>
                  <TextInput type="date" aria-label="기간 끝" value={to} onChange={(e) => setTo(e.currentTarget.value)} error={periodError !== null && isDay(from)} style={{ flex: 1, minWidth: 0 }} />
                </div>
                <Group gap={4}>
                  {presets.map((p) => (
                    <Button
                      key={p.label}
                      size="xs"
                      variant={from === p.range.from && to === p.range.to ? 'light' : 'subtle'}
                      onClick={() => {
                        setFrom(p.range.from)
                        setTo(p.range.to)
                      }}
                    >
                      {p.label}
                    </Button>
                  ))}
                </Group>
              </>
            ) : null}
            {tab === 'journal' ? (
              <Select
                aria-label="계정으로 거르기"
                placeholder="모든 계정"
                data={accountOptions(accounts.data?.items ?? [])}
                value={account}
                onChange={setAccount}
                searchable
                clearable
                nothingFoundMessage="없는 계정입니다"
                style={{ flex: '1 1 200px', maxWidth: 300 }}
              />
            ) : null}
          </Toolbar>
        ) : null}

        <Tabs.Panel value="journal">
          {period ? (
            <Journal period={period} account={account} types={accounts.data?.items ?? []} canPost={canPost} version={version} />
          ) : (
            <Notice tone="warn">{periodError}</Notice>
          )}
        </Tabs.Panel>
        <Tabs.Panel value="trial">{period ? <TrialBalance period={period} version={version} /> : <Notice tone="warn">{periodError}</Notice>}</Tabs.Panel>
        <Tabs.Panel value="pl">
          {plScope === 'all' ? (
            <ProjectPl period={null} version={version} />
          ) : period ? (
            <ProjectPl period={period} version={version} />
          ) : (
            <Notice tone="warn">{periodError}</Notice>
          )}
        </Tabs.Panel>
        <Tabs.Panel value="accounts">
          <Accounts accounts={accounts} />
        </Tabs.Panel>
      </Tabs>

      {canPost ? <ManualEntryModal opened={manual} onClose={() => setManual(false)} accounts={accounts.data?.items ?? []} onPosted={() => setVersion((v) => v + 1)} /> : null}
    </>
  )
}

// ------------------------------------------------------------- journal --

function Journal({ period, account, types, canPost, version }: { period: Period; account: string | null; types: AccountRow[]; canPost: boolean; version: number }): ReactNode {
  const ws = useWs()
  const [reversing, setReversing] = useState<JournalEntry | null>(null)
  const [bump, setBump] = useState(0)
  const journal = useAsync(
    (signal) => api.get<JournalResponse>(ws.apiPath(`/ledger/journal${qs({ from: period.from, to: period.to, account })}`), { signal }),
    [ws.code, period.from, period.to, account, version, bump],
  )

  return (
    <>
      {journal.initial ? (
        <FullLoader />
      ) : journal.error ? (
        <ErrorState error={journal.error} onRetry={journal.reload} home={ws.path('/')} />
      ) : journal.data!.items.length === 0 ? (
        <div className="bz-surface">
          <EmptyState title="이 기간에 기록된 전표가 없습니다">
            {account ? '고른 계정이 들어간 전표가 없습니다. 계정 거르기를 지우거나 기간을 넓혀 보세요.' : '기간을 넓혀 보세요.'}
          </EmptyState>
        </div>
      ) : (
        <Busy loading={journal.loading}>
          <JournalTable entries={journal.data!.items} account={account} types={types} canPost={canPost && journal.data!.can_post} onReverse={setReversing} />
        </Busy>
      )}
      <ReverseModal entry={reversing} onClose={() => setReversing(null)} onDone={() => setBump((b) => b + 1)} />
    </>
  )
}

function JournalTable({
  entries,
  account,
  types,
  canPost,
  onReverse,
}: {
  entries: JournalEntry[]
  account: string | null
  types: AccountRow[]
  canPost: boolean
  onReverse(entry: JournalEntry): void
}): ReactNode {
  const byId = new Map(entries.map((e) => [e.id, e]))
  const lines = entries.flatMap((e) => e.lines)
  const debit = lines.reduce((s, l) => s + Number(l.debit), 0)
  const credit = lines.reduce((s, l) => s + Number(l.credit), 0)
  const picked = account ? types.find((a) => a.code === account) : undefined
  const hits = account ? lines.filter((l) => l.account_code === account) : []
  const hitDebit = hits.reduce((s, l) => s + Number(l.debit), 0)
  const hitCredit = hits.reduce((s, l) => s + Number(l.credit), 0)
  const net = debitNormal(picked?.type) ? hitDebit - hitCredit : hitCredit - hitDebit

  return (
    <>
      {account ? (
        <Figures
          label="고른 계정의 기간 합계"
          items={[
            { label: `${account} ${picked?.name ?? ''} 차변 합계`, value: krw(hitDebit) },
            { label: '대변 합계', value: krw(hitCredit) },
            {
              label: '기간 증감',
              value: krw(net),
              tone: net < 0 ? 'danger' : undefined,
              hint: debitNormal(picked?.type) ? '차변 − 대변 (자산·비용 계정)' : '대변 − 차변 (부채·자본·수익 계정)',
            },
          ]}
        />
      ) : null}
      <p className="fin-summary">
        전표 {entries.length.toLocaleString('ko-KR')}건
        {entries.length >= 500 ? ' (최근 500건까지 보입니다. 기간을 줄이거나 CSV로 내려받으세요.)' : ''}
        {account ? ' · 고른 계정이 들어간 전표의 모든 줄을 보여 줍니다.' : ''}
      </p>
      <div className="bz-table-box">
        <table className="bz-grid-table fin-journal" data-cards="true">
          <thead>
            <tr>
              <th scope="col">계정과목</th>
              <th scope="col" className="bz-num">
                차변
              </th>
              <th scope="col" className="bz-num">
                대변
              </th>
              <th scope="col">프로젝트·거래처</th>
              <th scope="col">메모</th>
            </tr>
          </thead>
          {entries.map((e) => (
            <tbody key={e.id}>
              <tr className="fin-entry-head">
                <td colSpan={5} data-label="">
                  <EntryHead entry={e} original={e.reversal_of ? byId.get(e.reversal_of) : undefined} canPost={canPost} onReverse={onReverse} />
                </td>
              </tr>
              {e.lines.map((l) => {
                const party = [l.project_name, l.customer_name].filter(Boolean).join(' · ')
                return (
                  <tr key={l.line_no} data-hit={account && l.account_code === account ? 'true' : undefined}>
                    <td data-label="계정과목">
                      <AccountName code={l.account_code} name={l.account_name} />
                    </td>
                    <NumCell label="차변" value={l.debit} blankZero />
                    <NumCell label="대변" value={l.credit} blankZero />
                    <td data-label="프로젝트·거래처" data-empty={party ? undefined : 'true'}>
                      {party}
                    </td>
                    <td data-label="메모" data-empty={l.memo ? undefined : 'true'}>
                      {l.memo}
                    </td>
                  </tr>
                )
              })}
            </tbody>
          ))}
          <tfoot>
            <tr>
              <td data-label="">합계</td>
              <NumCell label="차변 합계" value={debit} />
              <NumCell label="대변 합계" value={credit} />
              <td colSpan={2} data-label="" data-empty={debit === credit ? 'true' : undefined}>
                {debit === credit ? '' : <Tag tone="danger">차대 불일치</Tag>}
              </td>
            </tr>
          </tfoot>
        </table>
      </div>
    </>
  )
}

function EntryHead({ entry: e, original, canPost, onReverse }: { entry: JournalEntry; original: JournalEntry | undefined; canPost: boolean; onReverse(entry: JournalEntry): void }): ReactNode {
  const ws = useWs()
  const source = e.source_id ? SOURCE_PAGE[e.source_type] : undefined
  const amount = e.lines.reduce((s, l) => s + Number(l.debit), 0)
  return (
    <div className="fin-entry-head-inner">
      <div style={{ display: 'flex', flexWrap: 'wrap', alignItems: 'center', gap: '4px 10px', minWidth: 0 }}>
        <b className="bz-num">{e.entry_no}</b>
        <span className="bz-num">{date(e.entry_date)}</span>
        <Tag tone={e.kind === 'manual' ? 'brand' : e.kind === 'reversal' ? 'warn' : 'neutral'}>{JOURNAL_KIND[e.kind] ?? e.kind}</Tag>
        {e.reversed ? (
          <Tag tone="neutral" title="이 전표를 되돌린 역분개 전표가 있습니다">
            역분개됨
          </Tag>
        ) : null}
        {e.reversal_of ? <Tag tone="warn">{original ? `${original.entry_no} 되돌림` : '역분개 전표'}</Tag> : null}
        <span style={{ minWidth: 0 }}>{e.memo}</span>
        {source && e.source_id ? <InLink to={ws.path(`${source.path}/${e.source_id}`)}>{source.label}</InLink> : null}
        {e.created_by_name ? <span className="bz-muted" style={{ fontSize: '0.75rem' }}>{e.created_by_name}</span> : null}
      </div>
      <div style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
        <span className="bz-num" style={{ fontWeight: 650 }}>
          {krw(amount)}
        </span>
        {canPost && !e.reversed && !e.reversal_of ? (
          <Button size="compact-xs" variant="default" color="red" aria-label={`${e.entry_no} 역분개`} onClick={() => onReverse(e)}>
            역분개
          </Button>
        ) : null}
      </div>
    </div>
  )
}

function ReverseModal({ entry, onClose, onDone }: { entry: JournalEntry | null; onClose(): void; onDone(): void }): ReactNode {
  const ws = useWs()
  // Kept while the dialog animates closed.
  const [shown, setShown] = useState<JournalEntry | null>(entry)
  const [memo, setMemo] = useState('')
  const [entryDate, setEntryDate] = useState(today())
  if (entry && entry !== shown) {
    setShown(entry)
    setMemo('')
    setEntryDate(today())
  }
  const early = shown !== null && isDay(entryDate) && entryDate < shown.entry_date
  return (
    <ConfirmModal
      opened={entry !== null}
      onClose={onClose}
      title={`${shown?.entry_no ?? '전표'} 역분개`}
      confirmLabel="역분개 전표 기록"
      danger
      disabled={!isDay(entryDate)}
      onConfirm={async () => {
        if (!shown) return
        await api.post(ws.apiPath(`/ledger/journal/${shown.id}/reverse`), { memo: memo.trim(), entry_date: entryDate })
        toast.ok(`역분개 전표를 ${date(entryDate)} 날짜로 기록했습니다.`)
        onDone()
      }}
    >
      {shown ? (
        <>
          <Text size="sm">
            이 전표의 차변과 대변을 맞바꾼 새 전표를 아래 날짜로 기록합니다. 원래 전표는 그대로 남고, 한 전표는 한 번만 역분개할 수 있으며 역분개 전표는 다시
            역분개하지 않습니다.
          </Text>
          {shown.kind !== 'manual' ? (
            <Notice tone="warn">
              자동으로 기록된 전표({JOURNAL_KIND[shown.kind] ?? shown.kind})입니다. 원장만 되돌리고 원래 문서(청구·경비·매입·지급)의 상태는 바뀌지 않습니다. 매출 청구는
              청구 화면의 &lsquo;청구 취소&rsquo;로 되돌리세요.
            </Notice>
          ) : null}
          <PostingPreview
            title="기록될 역분개"
            lines={shown.lines.map((l) => ({ code: l.account_code, name: l.account_name, debit: Number(l.credit), credit: Number(l.debit) }))}
          />
          <TextInput
            type="date"
            label="역분개일"
            required
            value={entryDate}
            onChange={(e) => setEntryDate(e.currentTarget.value)}
            description={
              early
                ? `원래 전표일(${date(shown.entry_date)})보다 앞선 날짜입니다.`
                : '기본은 오늘. 원래 전표와 같은 달로 되돌리려면 그 달의 날짜를 적습니다.'
            }
            error={isDay(entryDate) ? undefined : '날짜를 입력해 주세요.'}
          />
          <TextInput
            label="적요"
            placeholder={`역분개: ${shown.entry_no}`}
            description="비워 두면 위 문구로 기록됩니다."
            maxLength={300}
            value={memo}
            onChange={(e) => setMemo(e.currentTarget.value)}
          />
        </>
      ) : null}
    </ConfirmModal>
  )
}

// ------------------------------------------------------- manual entry --

interface DraftLine {
  key: number
  account: string | null
  debit: Amount
  credit: Amount
  memo: string
}

function blankLine(key: number): DraftLine {
  return { key, account: null, debit: '', credit: '', memo: '' }
}

function ManualEntryModal({ opened, onClose, accounts, onPosted }: { opened: boolean; onClose(): void; accounts: AccountRow[]; onPosted(): void }): ReactNode {
  const phone = useMediaQuery('(max-width: 48em)')
  // The modal unmounts closed content, so every opening starts with a blank entry.
  return (
    <Modal opened={opened} onClose={onClose} title="수동 분개" size="xl" fullScreen={phone}>
      <ManualEntryForm accounts={accounts} onClose={onClose} onPosted={onPosted} />
    </Modal>
  )
}

function ManualEntryForm({ accounts, onClose, onPosted }: { accounts: AccountRow[]; onClose(): void; onPosted(): void }): ReactNode {
  const ws = useWs()
  const [entryDate, setEntryDate] = useState(today())
  const [memo, setMemo] = useState('')
  const [lines, setLines] = useState<DraftLine[]>(() => [blankLine(1), blankLine(2)])
  const [nextKey, setNextKey] = useState(3)
  const [busy, setBusy] = useState(false)
  const [error, setError] = useState<ApiError | null>(null)

  const options = accountOptions(accounts.filter((a) => a.active))
  const debit = lines.reduce((s, l) => s + amt(l.debit), 0)
  const credit = lines.reduce((s, l) => s + amt(l.credit), 0)
  const diff = debit - credit

  const problems: string[] = []
  if (!isDay(entryDate)) problems.push('전표일을 입력해 주세요.')
  if (!memo.trim()) problems.push('적요를 입력해 주세요.')
  lines.forEach((l, i) => {
    if (!l.account) problems.push(`${i + 1}번째 줄: 계정을 고르세요.`)
    if (amt(l.debit) > 0 === amt(l.credit) > 0) problems.push(`${i + 1}번째 줄: 차변이나 대변 중 한쪽에만 금액을 적으세요.`)
  })
  if (debit > 0 && diff !== 0) problems.push(`차변 합계와 대변 합계가 ${krw(Math.abs(diff))} 다릅니다.`)
  const ready = problems.length === 0

  const update = (key: number, patch: Partial<DraftLine>) => setLines((prev) => prev.map((l) => (l.key === key ? { ...l, ...patch } : l)))
  const addLine = () => {
    setLines((prev) => [...prev, blankLine(nextKey)])
    setNextKey((k) => k + 1)
  }
  const removeLine = (key: number) => setLines((prev) => (prev.length <= 2 ? prev : prev.filter((l) => l.key !== key)))
  // The difference, put on the side that is short, in the last line that is still empty.
  const fillDifference = () => {
    const target = [...lines].reverse().find((l) => amt(l.debit) === 0 && amt(l.credit) === 0)
    if (!target || diff === 0) return
    update(target.key, diff > 0 ? { credit: diff, debit: '' } : { debit: -diff, credit: '' })
  }
  const canFill = diff !== 0 && lines.some((l) => amt(l.debit) === 0 && amt(l.credit) === 0)

  const post = async () => {
    setBusy(true)
    setError(null)
    try {
      await api.post<{ id: string }>(ws.apiPath('/ledger/journal'), {
        entry_date: entryDate,
        memo: memo.trim(),
        lines: lines.map((l) => ({ account: l.account, debit: amt(l.debit), credit: amt(l.credit), memo: l.memo.trim() })),
      })
      toast.ok('수동 분개를 기록했습니다.')
      onPosted()
      onClose()
    } catch (err) {
      if (err instanceof ApiError) setError(err)
      else toast.error(err)
    } finally {
      setBusy(false)
    }
  }

  return (
    <Stack>
      <Text size="sm" c="dimmed">
        자동으로 기록되지 않는 거래(자본금 납입, 이자, 감가상각 등)를 적습니다. 한 줄에는 차변이나 대변 중 한쪽만 적고, 차변 합계와 대변 합계가 같아야 기록됩니다. 기록한
        전표는 고칠 수 없고 역분개로만 되돌립니다.
      </Text>
      <SimpleGrid cols={{ base: 1, sm: 2 }}>
        <TextInput type="date" label="전표일" required value={entryDate} onChange={(e) => setEntryDate(e.currentTarget.value)} error={fieldError(error, 'entry_date')} />
        <TextInput
          label="적요"
          required
          maxLength={300}
          placeholder="예: 자본금 납입"
          value={memo}
          onChange={(e) => setMemo(e.currentTarget.value)}
          error={fieldError(error, 'memo')}
        />
      </SimpleGrid>

      <Stack gap="xs" role="group" aria-label="분개 줄">
        {lines.map((l, i) => (
          <div key={l.key} className="fin-jline">
            <Select
              className="fin-jl-acct"
              aria-label={`${i + 1}번째 줄 계정`}
              placeholder="계정 고르기"
              data={options}
              value={l.account}
              onChange={(v) => update(l.key, { account: v })}
              searchable
              nothingFoundMessage="없는 계정입니다"
              error={fieldError(error, `lines[${i}].account`)}
            />
            <MoneyInput
              className="fin-jl-debit"
              aria-label={`${i + 1}번째 줄 차변`}
              leftSection={<Text size="xs" c="dimmed">차변</Text>}
              leftSectionWidth={44}
              value={l.debit}
              onChange={(v) => update(l.key, amt(v) > 0 ? { debit: v, credit: '' } : { debit: v })}
            />
            <MoneyInput
              className="fin-jl-credit"
              aria-label={`${i + 1}번째 줄 대변`}
              leftSection={<Text size="xs" c="dimmed">대변</Text>}
              leftSectionWidth={44}
              value={l.credit}
              onChange={(v) => update(l.key, amt(v) > 0 ? { credit: v, debit: '' } : { credit: v })}
            />
            <TextInput
              className="fin-jl-memo"
              aria-label={`${i + 1}번째 줄 메모`}
              placeholder="줄 메모 (선택)"
              maxLength={200}
              value={l.memo}
              onChange={(e) => update(l.key, { memo: e.currentTarget.value })}
            />
            <ActionIcon className="fin-jl-del" variant="subtle" color="gray" aria-label={`${i + 1}번째 줄 빼기`} disabled={lines.length <= 2} onClick={() => removeLine(l.key)}>
              <IconTrash size={16} />
            </ActionIcon>
          </div>
        ))}
      </Stack>

      <Group justify="space-between" gap="sm">
        <Group gap="xs">
          <Button variant="default" size="xs" leftSection={<IconPlus size={14} />} onClick={addLine} disabled={lines.length >= 50}>
            줄 더하기
          </Button>
          {canFill ? (
            <Button variant="subtle" size="xs" onClick={fillDifference}>
              빈 줄에 차액 채우기
            </Button>
          ) : null}
        </Group>
        <div aria-live="polite" style={{ display: 'flex', gap: 12, flexWrap: 'wrap', alignItems: 'center', fontSize: '0.875rem' }}>
          <span>
            차변 합계 <b className="bz-num">{krw(debit)}</b>
          </span>
          <span>
            대변 합계 <b className="bz-num">{krw(credit)}</b>
          </span>
          {debit === 0 && credit === 0 ? (
            <Tag tone="neutral">금액 없음</Tag>
          ) : diff === 0 ? (
            <Tag tone="ok">차대 일치</Tag>
          ) : (
            <Tag tone="danger">
              {diff > 0 ? '차변이' : '대변이'} {krw(Math.abs(diff))} 많음
            </Tag>
          )}
        </div>
      </Group>

      <FormProblem error={error} fields={['entry_date', 'memo', ...lines.map((_, i) => `lines[${i}].account`)]} />
      <Group justify="space-between" align="center" gap="sm">
        <Text size="xs" c="dimmed" style={{ flex: '1 1 200px' }}>
          {ready ? '기록할 수 있습니다.' : problems[0]}
        </Text>
        <Group gap="xs">
          <Button variant="default" onClick={onClose}>
            닫기
          </Button>
          <Button onClick={() => void post()} loading={busy} disabled={!ready}>
            전표 기록
          </Button>
        </Group>
      </Group>
    </Stack>
  )
}

// ------------------------------------------------------- trial balance --

function TrialBalance({ period, version }: { period: Period; version: number }): ReactNode {
  const ws = useWs()
  const tb = useAsync(
    (signal) => api.get<TrialResponse>(ws.apiPath(`/ledger/trial-balance${qs({ from: period.from, to: period.to })}`), { signal }),
    [ws.code, period.from, period.to, version],
  )
  if (tb.initial) return <FullLoader />
  if (tb.error) return <ErrorState error={tb.error} onRetry={tb.reload} home={ws.path('/')} />
  const d = tb.data!
  const revenue = Number(d.income.revenue)
  const profit = Number(d.income.profit)
  const margin = revenue > 0 ? Math.round((profit / revenue) * 1000) / 10 : null

  return (
    <Busy loading={tb.loading}>
      <Figures
        label="기간 손익"
        items={[
          { label: '수익', value: krw(revenue) },
          { label: '비용', value: krw(d.income.expense) },
          {
            label: profit < 0 ? '손실' : '이익',
            value: krw(profit),
            tone: profit < 0 ? 'danger' : undefined,
            hint: margin === null ? undefined : `이익률 ${margin.toLocaleString('ko-KR')}%`,
          },
        ]}
      />
      {d.items.length === 0 ? (
        <div className="bz-surface">
          <EmptyState title="이 기간에 움직인 계정이 없습니다">기간을 넓혀 보세요.</EmptyState>
        </div>
      ) : (
