/** Project P&L for a period, or all time (period null) - only then is budget use meaningful. */
function ProjectPl({ period, version }: { period: Period | null; version: number }): ReactNode {
  const ws = useWs()
  const [all, setAll] = useState(false)
  const pl = useAsync(
    (signal) => api.get<PlResponse>(ws.apiPath(`/ledger/project-pl${qs({ from: period?.from, to: period?.to })}`), { signal }),
    [ws.code, period?.from, period?.to, version],
  )
  if (pl.initial) return <FullLoader />
  if (pl.error) return <ErrorState error={pl.error} onRetry={pl.reload} home={ws.path('/')} />
  const d = pl.data!
  const lifetime = d.from === null && d.to === null
  const items = d.items
  const rows = all ? items : items.filter((r) => Number(r.revenue) !== 0 || Number(r.cost) !== 0)
  const revenue = rows.reduce((s, r) => s + Number(r.revenue), 0)
  const cost = rows.reduce((s, r) => s + Number(r.cost), 0)
  const profit = revenue - cost
  const margin = revenue > 0 ? Math.round((profit / revenue) * 1000) / 10 : null

  return (
    <Busy loading={pl.loading}>
      <Toolbar>
        <Switch label="거래 없는 프로젝트도 보기" checked={all} onChange={(e) => setAll(e.currentTarget.checked)} />
        <Text size="xs" c="dimmed" style={{ flex: '1 1 260px' }}>
          {lifetime ? '전체 기간' : `${date(d.from)} ~ ${date(d.to)}`}. 분개 줄에 프로젝트가 연결된 금액만 셉니다(청구·경비·매입에서 프로젝트를 고른 것).
          {lifetime ? '' : ' 예산은 프로젝트 전체에 대한 것이라 기간을 정하면 예산 대비 비용은 보이지 않습니다.'}
        </Text>
      </Toolbar>
      {rows.length === 0 ? (
        <div className="bz-surface">
          <EmptyState title={items.length === 0 ? '프로젝트가 없습니다' : '프로젝트에 묶인 매출·비용이 없습니다'}>
            청구·경비·매입을 만들 때 프로젝트를 고르면 여기에 손익이 쌓입니다.
          </EmptyState>
        </div>
      ) : (
        <div className="bz-table-box">
          <table className="bz-grid-table" data-cards="true">
            <thead>
              <tr>
                <th scope="col">프로젝트</th>
                <th scope="col">상태</th>
                <th scope="col" className="bz-num">
                  매출
                </th>
                <th scope="col" className="bz-num">
                  비용
                </th>
                <th scope="col" className="bz-num">
                  이익
                </th>
                <th scope="col" className="bz-num">
                  이익률
                </th>
                <th scope="col" className="bz-num">
                  예산
                </th>
                {lifetime ? (
                  <th scope="col" className="bz-num">
                    예산 대비 비용
                  </th>
                ) : null}
              </tr>
            </thead>
            <tbody>
              {rows.map((r) => {
                const budget = r.budget === null ? null : Number(r.budget)
                const used = budget && budget > 0 ? Math.round((Number(r.cost) / budget) * 1000) / 10 : null
                return (
                  <tr key={r.project_id}>
                    <td data-label="프로젝트">
                      <InLink to={ws.path(`/work/projects/${r.project_id}`)}>
                        <span className="fin-code">{r.code}</span>
                        {r.name}
                      </InLink>
                    </td>
                    <td data-label="상태">
                      <StatusBadge map={PROJECT_STATUS} value={r.status} />
                    </td>
                    <NumCell label="매출" value={r.revenue} />
                    <NumCell label="비용" value={r.cost} />
                    <NumCell label="이익" value={r.profit} strong danger={Number(r.profit) < 0} />
                    <td className={`bz-num${r.margin !== null && r.margin < 0 ? ' fin-danger' : ''}`} data-label="이익률">
                      {r.margin === null ? '—' : `${r.margin.toLocaleString('ko-KR')}%`}
                    </td>
                    <td className="bz-num" data-label="예산">
                      {budget === null ? '—' : krw(budget)}
                    </td>
                    {lifetime ? (
                      <td className={`bz-num${used !== null && used > 100 ? ' fin-danger' : ''}`} data-label="예산 대비 비용">
                        {used === null ? '—' : `${used.toLocaleString('ko-KR')}%`}
                      </td>
                    ) : null}
                  </tr>
                )
              })}
            </tbody>
            <tfoot>
              <tr>
                <td colSpan={2} data-label="">
                  합계 ({rows.length.toLocaleString('ko-KR')}개)
                </td>
                <NumCell label="매출 합계" value={revenue} />
                <NumCell label="비용 합계" value={cost} />
                <NumCell label="이익 합계" value={profit} danger={profit < 0} />
                <td className="bz-num" data-label="이익률">
                  {margin === null ? '—' : `${margin.toLocaleString('ko-KR')}%`}
                </td>
                <td colSpan={lifetime ? 2 : 1} data-label="" data-empty="true" />
              </tr>
            </tfoot>
          </table>
        </div>
      )}
    </Busy>
  )
}

