/** Rename an account, and for a cost account whether expense claims may use it. */
function AccountEditForm({ account, onClose, onSaved }: { account: AccountRow; onClose(): void; onSaved(): void }): ReactNode {
  const ws = useWs()
  const [name, setName] = useState(account.name)
  const [expenseCategory, setExpenseCategory] = useState(account.expense_category)
  const [busy, setBusy] = useState(false)
  const [error, setError] = useState<ApiError | null>(null)
  const changes: { name?: string; expense_category?: boolean } = {}
  if (name.trim() !== account.name) changes.name = name.trim()
  if (account.type === 'expense' && expenseCategory !== account.expense_category) changes.expense_category = expenseCategory
  const ready = name.trim().length > 0 && Object.keys(changes).length > 0

  const save = async () => {
    setBusy(true)
    setError(null)
    try {
      await api.patch(ws.apiPath(`/ledger/accounts/${account.code}`), changes)
      toast.ok('계정을 고쳤습니다.')
      onSaved()
      onClose()
    } catch (err) {
      if (err instanceof ApiError) setError(err)
      else toast.error(err)
    } finally {
      setBusy(false)
    }
  }

  return (
    <Stack>
      <Text size="sm" c="dimmed">
        {ACCOUNT_TYPE[account.type] ?? account.type} 계정 · 코드 {account.code}는 바꿀 수 없습니다. 이름을 바꾸면 지난 전표에도 새 이름으로 보입니다.
      </Text>
      <TextInput label="계정과목 이름" required maxLength={40} value={name} onChange={(e) => setName(e.currentTarget.value)} error={fieldError(error, 'name')} />
      {account.type === 'expense' ? (
        <Checkbox
          label="경비 분류로 쓰기"
          description="경비 청구의 분류 목록에 넣습니다. 빼도 이미 청구한 경비는 그대로입니다."
          checked={expenseCategory}
          onChange={(e) => setExpenseCategory(e.currentTarget.checked)}
          error={fieldError(error, 'expense_category')}
        />
      ) : null}
      {error && !Object.keys(error.fieldErrors).length ? <Notice tone="warn">{error.message}</Notice> : null}
      <Group justify="flex-end">
        <Button variant="default" onClick={onClose}>
          닫기
        </Button>
        <Button onClick={() => void save()} loading={busy} disabled={!ready}>
          저장
        </Button>
      </Group>
    </Stack>
  )
}

/** 끄기/켜기: an account turned off can no longer be picked; what it already holds stays. */
function ToggleAccountModal({ account, onClose, onDone }: { account: AccountRow | null; onClose(): void; onDone(): void }): ReactNode {
  const ws = useWs()
  // Kept while the dialog animates closed.
  const [shown, setShown] = useState<AccountRow | null>(account)
  if (account && account !== shown) setShown(account)
  const turningOff = shown?.active ?? true
  return (
    <ConfirmModal
      opened={account !== null}
      onClose={onClose}
      title={`${shown?.code ?? ''} ${shown?.name ?? ''} ${turningOff ? '끄기' : '켜기'}`.trim()}
      confirmLabel={turningOff ? '계정 끄기' : '계정 켜기'}
      danger={turningOff}
      onConfirm={async () => {
        if (!shown) return
        await api.patch(ws.apiPath(`/ledger/accounts/${shown.code}`), { active: !shown.active })
        toast.ok(turningOff ? '계정을 껐습니다.' : '계정을 다시 켰습니다.')
        onDone()
      }}
    >
      <Text size="sm">
        {turningOff
          ? '끄면 수동 분개, 매입의 비용 계정, 경비 분류에서 더는 고를 수 없습니다. 이미 기록된 전표와 잔액은 그대로 남고, 언제든 다시 켤 수 있습니다.'
          : '켜면 수동 분개와 매입에서 다시 고를 수 있습니다. 경비 분류로 표시된 비용 계정이면 경비 청구에도 다시 보입니다.'}
      </Text>
    </ConfirmModal>
  )
}

function AccountForm({ existing, onClose, onAdded }: { existing: AccountRow[]; onClose(): void; onAdded(): void }): ReactNode {
  const ws = useWs()
  const [code, setCode] = useState('')
  const [name, setName] = useState('')
  const [type, setType] = useState<string>('expense')
  const [expenseCategory, setExpenseCategory] = useState(true)
  const [busy, setBusy] = useState(false)
  const [error, setError] = useState<ApiError | null>(null)

  const codeOk = /^\d{3,6}$/.test(code)
  const taken = existing.some((a) => a.code === code)
  const ready = codeOk && !taken && name.trim().length > 0

  const save = async () => {
    setBusy(true)
    setError(null)
    try {
      await api.post(ws.apiPath('/ledger/accounts'), { code, name: name.trim(), type, expense_category: type === 'expense' && expenseCategory })
      toast.ok(`${code} ${name.trim()} 계정을 추가했습니다.`)
