          value={code}
          onChange={(e) => setCode(e.currentTarget.value.replace(/\D/g, ''))}
          error={taken ? '같은 코드의 계정이 있습니다.' : fieldError(error, 'code')}
          description="숫자 3~6자리"
        />
        <Select
          label="구분"
          required
          allowDeselect={false}
          data={ACCOUNT_TYPES.map((t) => ({ value: t, label: ACCOUNT_TYPE[t] ?? t }))}
          value={type}
          onChange={(v) => setType(v ?? 'expense')}
          error={fieldError(error, 'type')}
        />
      </SimpleGrid>
      <TextInput label="계정과목 이름" required maxLength={40} placeholder="예: 교육훈련비" value={name} onChange={(e) => setName(e.currentTarget.value)} error={fieldError(error, 'name')} />
      {type === 'expense' ? (
        <Checkbox
          label="경비 분류로 쓰기"
          description="경비 청구의 분류 목록에 넣습니다."
          checked={expenseCategory}
          onChange={(e) => setExpenseCategory(e.currentTarget.checked)}
        />
      ) : null}
      <Text size="xs" c="dimmed">
        추가한 계정은 지울 수 없습니다. 코드는 원장과 CSV에 그대로 남습니다.
      </Text>
      {error && !Object.keys(error.fieldErrors).length ? <Notice tone="warn">{error.message}</Notice> : null}
      <Group justify="flex-end">
        <Button variant="default" onClick={onClose}>
          닫기
        </Button>
        <Button onClick={() => void save()} loading={busy} disabled={!ready}>
          추가
        </Button>
      </Group>
    </Stack>
  )
}
