/**
 * A small Markdown renderer for kit descriptions, guides and policy
 * documents. It builds React elements only - no HTML string, no
 * dangerouslySetInnerHTML - so markup in the text stays text.
 *
 * Supported: headings (##, ###), paragraphs, lists (-, 1.), task lists,
 * fenced code, inline code, bold, links, tables, quotes, rules. Links: only
 * http(s) and paths on this site; outside links open in a new tab with
 * noopener noreferrer nofollow; anything else (javascript:, data:) stays
 * text. Images are not drawn. Scrollable code and tables take keyboard focus.
 */
import { Fragment, type ReactNode } from 'react'

function safeHref(href: string): { href: string; external: boolean } | null {
  const h = href.trim()
  if (/^\/(?!\/)/.test(h)) return { href: h, external: false }
  try {
    const u = new URL(h)
    if (u.protocol === 'https:' || u.protocol === 'http:') return { href: u.toString(), external: true }
  } catch {
    /* 링크로 만들지 않는다 */
  }
  return null
}

function inline(text: string, keyBase: string): ReactNode[] {
  const out: ReactNode[] = []
  const re = /(`[^`]+`)|(\*\*[^*]+\*\*)|(\[[^\]]+\]\([^)\s]+\))/g
  let last = 0
  let m: RegExpExecArray | null
  let i = 0
  while ((m = re.exec(text))) {
    if (m.index > last) out.push(text.slice(last, m.index))
    const tok = m[0]
    const key = `${keyBase}-${i++}`
    if (tok.startsWith('`')) out.push(<code key={key}>{tok.slice(1, -1)}</code>)
    else if (tok.startsWith('**')) out.push(<strong key={key}>{tok.slice(2, -2)}</strong>)
    else {
      const lm = /^\[([^\]]+)\]\(([^)\s]+)\)$/.exec(tok)!
      const link = safeHref(lm[2]!)
      out.push(
        link ? (
          <a key={key} href={link.href} {...(link.external ? { target: '_blank', rel: 'noopener noreferrer nofollow' } : {})}>
            {lm[1]}
          </a>
        ) : (
          <span key={key}>{lm[1]}</span>
        ),
      )
    }
    last = m.index + tok.length
  }
  if (last < text.length) out.push(text.slice(last))
  return out
}

function splitRow(line: string): string[] {
  const t = line.trim().replace(/^\|/, '').replace(/\|$/, '')
  const cells: string[] = []
  let cur = ''
  for (let i = 0; i < t.length; i++) {
    if (t[i] === '\\' && t[i + 1] === '|') {
      cur += '|'
      i++
    } else if (t[i] === '|') {
      cells.push(cur.trim())
      cur = ''
    } else cur += t[i]
  }
  cells.push(cur.trim())
  return cells
}

export function Markdown({ source, className = 'bz-prose' }: { source: string; className?: string }) {
  const lines = (source ?? '').replace(/\r\n?/g, '\n').split('\n')
  const blocks: ReactNode[] = []
  let i = 0
  let k = 0
  while (i < lines.length) {
    const line = lines[i]!
    const key = `b${k++}`
    if (/^```/.test(line)) {
      const body: string[] = []
      i++
      while (i < lines.length && !/^```/.test(lines[i]!)) body.push(lines[i++]!)
      i++
      // 가로로 스크롤되는 코드 블록은 키보드로도 스크롤할 수 있게 초점을 받는다
      blocks.push(
        <pre key={key} tabIndex={0}>
          <code>{body.join('\n')}</code>
        </pre>,
      )
      continue
    }
    if (!line.trim()) {
      i++
      continue
    }
    const h = /^(#{1,4})\s+(.*)$/.exec(line)
    if (h) {
      const level = Math.min(4, h[1]!.length + 1)
      const content = inline(h[2]!, key)
      blocks.push(level === 2 ? <h2 key={key}>{content}</h2> : level === 3 ? <h3 key={key}>{content}</h3> : <h4 key={key}>{content}</h4>)
      i++
      continue
    }
    if (/^(-{3,}|\*{3,})\s*$/.test(line)) {
      blocks.push(<hr key={key} />)
      i++
      continue
    }
    if (/^\s*\|/.test(line) && i + 1 < lines.length && /^\s*\|?\s*:?-{3,}/.test(lines[i + 1]!)) {
      const head = splitRow(line)
      i += 2
      const rows: string[][] = []
      while (i < lines.length && /^\s*\|/.test(lines[i]!)) rows.push(splitRow(lines[i++]!))
      blocks.push(
        <div key={key} className="bz-table-scroll" tabIndex={0}>
        <table>
          <thead>
            <tr>{head.map((c, j) => <th key={j}>{inline(c, `${key}h${j}`)}</th>)}</tr>
          </thead>
          <tbody>
            {rows.map((r, ri) => (
              <tr key={ri}>{r.map((c, j) => <td key={j}>{inline(c, `${key}r${ri}c${j}`)}</td>)}</tr>
            ))}
          </tbody>
        </table>
        </div>,
      )
      continue
    }
    if (/^>\s?/.test(line)) {
      const body: string[] = []
      while (i < lines.length && /^>\s?/.test(lines[i]!)) body.push(lines[i++]!.replace(/^>\s?/, ''))
      blocks.push(<blockquote key={key}>{inline(body.join(' '), key)}</blockquote>)
      continue
    }
    if (/^\s*([-*]|\d+\.)\s+/.test(line)) {
      const ordered = /^\s*\d+\./.test(line)
      const items: { text: string; sub: string[] }[] = []
      while (i < lines.length && (/^\s*([-*]|\d+\.)\s+/.test(lines[i]!) || /^\s{2,}\S/.test(lines[i]!))) {
        const l = lines[i]!
        if (/^\s{2,}([-*])\s+/.test(l) && items.length) items[items.length - 1]!.sub.push(l.replace(/^\s+[-*]\s+/, ''))
        else if (/^\s{2,}\S/.test(l) && !/^\s*([-*]|\d+\.)\s+/.test(l) && items.length) items[items.length - 1]!.text += ` ${l.trim()}`
        else items.push({ text: l.replace(/^\s*([-*]|\d+\.)\s+/, ''), sub: [] })
        i++
      }
      const lis = items.map((it, j) => {
        const task = /^\[( |x)\]\s+/i.exec(it.text)
        return (
          <li key={j} className={task ? 'task' : undefined}>
            {task ? <span aria-hidden="true">{task[1] === ' ' ? '☐ ' : '☑ '}</span> : null}
            {inline(task ? it.text.slice(task[0].length) : it.text, `${key}i${j}`)}
            {it.sub.length ? (
              <ul>
                {it.sub.map((s, si) => (
                  <li key={si}>{inline(s, `${key}i${j}s${si}`)}</li>
                ))}
              </ul>
            ) : null}
          </li>
        )
      })
      blocks.push(ordered ? <ol key={key}>{lis}</ol> : <ul key={key}>{lis}</ul>)
      continue
    }
    const para: string[] = []
    while (i < lines.length && lines[i]!.trim() && !/^(#{1,4}\s|```|>\s?|\s*([-*]|\d+\.)\s+|\s*\|)/.test(lines[i]!)) para.push(lines[i++]!)
    if (para.length === 0) {
      para.push(lines[i++]!)
    }
    blocks.push(
      <p key={key}>
        {para.map((p, j) => (
          <Fragment key={j}>
            {j > 0 ? <br /> : null}
            {inline(p, `${key}p${j}`)}
          </Fragment>
        ))}
      </p>,
    )
  }
  return <div className={className}>{blocks}</div>
}
/**
 * A small typed validator. Hand-rolled rather than pulled in as a dependency
 * so the Workers bundle stays small and every message can be written in Korean
 * for direct display next to the field it belongs to.
 */
import { invalid, type FieldErrors } from '../errors.js'
import { koreanParticle } from './text.js'

/** 이름을 / 소개를, 이름은 / 키는 - the particle the word in front needs. */
const eul = (label: string) => `${label}${koreanParticle(label, '을', '를')}`
const eun = (label: string) => `${label}${koreanParticle(label, '은', '는')}`

export type Validator<T> = {
  /** Reads `value`, recording any problem under `path`. */
  run(value: unknown, path: string, errors: FieldErrors): T | undefined
  readonly optional?: boolean
}

type Shape = Record<string, Validator<unknown>>
type Infer<S extends Shape> = { [K in keyof S]: S[K] extends Validator<infer T> ? T : never }

/** Validate `input` against `shape`, throwing a single validation_failed error. */
export function parse<S extends Shape>(shape: S, input: unknown): Infer<S> {
  const errors: FieldErrors = {}
  const source = (typeof input === 'object' && input !== null ? input : {}) as Record<string, unknown>
  const out: Record<string, unknown> = {}
  for (const [key, validator] of Object.entries(shape)) {
    const result = validator.run(source[key], key, errors)
    if (result !== undefined) out[key] = result
  }
  if (Object.keys(errors).length > 0) throw invalid(errors)
  return out as Infer<S>
}

/** Validate a single value, e.g. a path or query parameter. */
export function parseOne<T>(validator: Validator<T>, value: unknown, path: string): T {
  const errors: FieldErrors = {}
  const result = validator.run(value, path, errors)
  if (Object.keys(errors).length > 0) throw invalid(errors)
  return result as T
}

function fail(errors: FieldErrors, path: string, message: string): undefined {
  if (!(path in errors)) errors[path] = message
  return undefined
}

const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i
// Deliberately conservative: one @, a dotted domain, no spaces or quoting.
const EMAIL_RE = /^[A-Za-z0-9!#$%&'*+/=?^_`{|}~.-]{1,64}@[A-Za-z0-9-]{1,63}(\.[A-Za-z0-9-]{1,63})+$/

export const v = {
  /** Trimmed string with length bounds. Rejects whitespace-only input. */
  string(opts: { min?: number; max: number; label: string; pattern?: RegExp; patternMessage?: string } ): Validator<string> {
    const min = opts.min ?? 1
    return {
      run(value, path, errors) {
        if (typeof value !== 'string') return fail(errors, path, `${eul(opts.label)} 입력해 주세요.`)
        const text = value.trim()
        if (text.length === 0 && min > 0) return fail(errors, path, `${eul(opts.label)} 입력해 주세요.`)
        if (text.length < min) return fail(errors, path, `${eun(opts.label)} ${min}자 이상이어야 합니다.`)
        if (text.length > opts.max) return fail(errors, path, `${eun(opts.label)} ${opts.max}자 이하여야 합니다.`)
        if (opts.pattern && !opts.pattern.test(text)) {
          return fail(errors, path, opts.patternMessage ?? `${opts.label} 형식이 올바르지 않습니다.`)
        }
        return text
      },
    }
  },

  /** String kept verbatim apart from newline normalisation (post bodies). */
  text(opts: { min?: number; max: number; label: string }): Validator<string> {
    const min = opts.min ?? 1
    return {
      run(value, path, errors) {
        if (typeof value !== 'string') return fail(errors, path, `${eul(opts.label)} 입력해 주세요.`)
        // Stripping control characters is the point: they are how a post smuggles
        // a terminal escape or a zero byte past a reader. The rule warns about
        // them appearing in a pattern by accident, which is not this.
        // eslint-disable-next-line no-control-regex
        const text = value.replace(/\r\n?/g, '\n').replace(/[\u0000-\u0008\u000b\u000c\u000e-\u001f]/g, '')
        // min: 0 means the field may be cleared - an empty 복지 section, a
        // report with no explanation. It used to be refused anyway, which
        // made clearing a field impossible and an empty optional message fail.
        if (min === 0 && text.trim().length === 0) return ''
        if (text.trim().length < Math.max(min, 1)) {
          return fail(errors, path, `${eul(opts.label)} 입력해 주세요.`)
        }
        if ([...text].length > opts.max) {
          return fail(errors, path, `${eun(opts.label)} ${opts.max}자 이하여야 합니다.`)
        }
        return text
      },
    }
  },

  int(opts: { min?: number; max?: number; label: string }): Validator<number> {
    return {
      run(value, path, errors) {
        const n = typeof value === 'string' && value.trim() !== '' ? Number(value) : value
        if (typeof n !== 'number' || !Number.isFinite(n) || !Number.isInteger(n)) {
          return fail(errors, path, `${eun(opts.label)} 정수여야 합니다.`)
        }
        if (opts.min !== undefined && n < opts.min) {
          return fail(errors, path, `${eun(opts.label)} ${opts.min} 이상이어야 합니다.`)
        }
        if (opts.max !== undefined && n > opts.max) {
          return fail(errors, path, `${eun(opts.label)} ${opts.max} 이하여야 합니다.`)
        }
        return n
      },
    }
  },

  bool(opts: { label: string }): Validator<boolean> {
    return {
      run(value, path, errors) {
        if (typeof value === 'boolean') return value
        if (value === 'true' || value === '1') return true
        if (value === 'false' || value === '0') return false
        return fail(errors, path, `${eun(opts.label)} true 또는 false여야 합니다.`)
      },
    }
  },

  uuid(opts: { label: string }): Validator<string> {
    return {
      run(value, path, errors) {
        if (typeof value !== 'string' || !UUID_RE.test(value)) {
          return fail(errors, path, `${opts.label} 식별자가 올바르지 않습니다.`)
        }
        return value.toLowerCase()
      },
    }
  },

  email(opts: { label?: string } = {}): Validator<string> {
    const label = opts.label ?? '이메일'
    return {
      run(value, path, errors) {
        if (typeof value !== 'string') return fail(errors, path, `${eul(label)} 입력해 주세요.`)
        const text = value.trim()
        if (text.length === 0) return fail(errors, path, `${eul(label)} 입력해 주세요.`)
        if (text.length > 254 || !EMAIL_RE.test(text)) {
          return fail(errors, path, `${label} 형식이 올바르지 않습니다.`)
        }
        return text
      },
    }
  },

  /** ISO-8601 instant; returns a Date. */
  instant(opts: { label: string }): Validator<Date> {
    return {
      run(value, path, errors) {
        if (typeof value !== 'string') return fail(errors, path, `${opts.label} 시각을 입력해 주세요.`)
        const d = new Date(value)
        if (Number.isNaN(d.getTime())) return fail(errors, path, `${opts.label} 시각 형식이 올바르지 않습니다.`)
        return d
      },
    }
  },

  oneOf<const T extends readonly string[]>(values: T, opts: { label: string }): Validator<T[number]> {
    return {
      run(value, path, errors) {
        if (typeof value !== 'string' || !values.includes(value)) {
          return fail(
            errors,
            path,
            values.length <= 6
              ? `${eun(opts.label)} ${values.join(', ')} 중 하나여야 합니다.`
              : `${opts.label} 값이 목록에 없습니다.`,
          )
        }
        return value as T[number]
      },
    }
  },

  array<T>(item: Validator<T>, opts: { min?: number; max: number; label: string }): Validator<T[]> {
    const min = opts.min ?? 0
    return {
      run(value, path, errors) {
        if (!Array.isArray(value)) return fail(errors, path, `${opts.label} 목록 형식이 올바르지 않습니다.`)
        if (value.length < min) return fail(errors, path, `${eun(opts.label)} ${min}개 이상이어야 합니다.`)
        if (value.length > opts.max) return fail(errors, path, `${eun(opts.label)} ${opts.max}개 이하여야 합니다.`)
        const out: T[] = []
        value.forEach((entry, index) => {
          const parsed = item.run(entry, `${path}[${index}]`, errors)
          if (parsed !== undefined) out.push(parsed)
        })
        return out
      },
    }
  },

  object<S extends Shape>(shape: S, opts: { label: string }): Validator<Infer<S>> {
    return {
      run(value, path, errors) {
        if (typeof value !== 'object' || value === null || Array.isArray(value)) {
          return fail(errors, path, `${opts.label} 형식이 올바르지 않습니다.`)
        }
        const source = value as Record<string, unknown>
        const out: Record<string, unknown> = {}
        for (const [key, validator] of Object.entries(shape)) {
          const parsed = validator.run(source[key], `${path}.${key}`, errors)
          if (parsed !== undefined) out[key] = parsed
        }
        return out as Infer<S>
      },
    }
  },

  /** A calendar day, 'YYYY-MM-DD', that exists. */
  day(opts: { label: string }): Validator<string> {
    return {
      run(value, path, errors) {
        if (typeof value !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(value)) {
          return fail(errors, path, `${opts.label} 날짜를 YYYY-MM-DD 로 입력해 주세요.`)
        }
        const d = new Date(`${value}T00:00:00Z`)
        if (Number.isNaN(d.getTime()) || d.toISOString().slice(0, 10) !== value) {
          return fail(errors, path, `${opts.label} 날짜가 올바르지 않습니다.`)
        }
        const year = d.getUTCFullYear()
        if (year < 2000 || year > 2100) return fail(errors, path, `${opts.label} 날짜가 범위를 벗어났습니다.`)
        return value
      },
    }
  },

  /** Whole won, 0 or more (the columns are numeric(18,0)). */
  money(opts: { label: string; min?: number; max?: number }): Validator<number> {
    const min = opts.min ?? 0
    const max = opts.max ?? 999_999_999_999
    return {
      run(value, path, errors) {
        const n = typeof value === 'string' && value.trim() !== '' ? Number(value.replace(/[,\s]/g, '')) : value
        if (typeof n !== 'number' || !Number.isFinite(n) || !Number.isInteger(n)) {
          return fail(errors, path, `${eun(opts.label)} 원 단위 정수여야 합니다.`)
        }
        if (n < min) return fail(errors, path, `${eun(opts.label)} ${min.toLocaleString('ko-KR')}원 이상이어야 합니다.`)
        if (n > max) return fail(errors, path, `${eun(opts.label)} 너무 큽니다.`)
        return n
      },
    }
  },

  /** A decimal number (quantities, rates). */
  decimal(opts: { label: string; min?: number; max?: number; places?: number }): Validator<number> {
    return {
      run(value, path, errors) {
        const n = typeof value === 'string' && value.trim() !== '' ? Number(value.replace(/[,\s]/g, '')) : value
        if (typeof n !== 'number' || !Number.isFinite(n)) return fail(errors, path, `${eun(opts.label)} 숫자여야 합니다.`)
        if (opts.min !== undefined && n < opts.min) return fail(errors, path, `${eun(opts.label)} ${opts.min} 이상이어야 합니다.`)
        if (opts.max !== undefined && n > opts.max) return fail(errors, path, `${eun(opts.label)} ${opts.max} 이하여야 합니다.`)
        const places = opts.places ?? 2
        return Math.round(n * 10 ** places) / 10 ** places
      },
    }
  },

  /** Any JSON value, used for settings whose shape the registry validates. */
  json(): Validator<unknown> {
    return { run: (value) => (value === undefined ? null : value) }
  },

  /** Makes a validator tolerate missing/empty input, substituting `fallback`. */
  optional<T>(inner: Validator<T>, fallback?: T): Validator<T | undefined> {
    return {
      optional: true,
      run(value, path, errors) {
        if (value === undefined || value === null || value === '') return fallback
        return inner.run(value, path, errors)
      },
    }
  },
}
/**
 * Time helpers. Everything is stored and compared in UTC; Korean local time is
 * a presentation concern, used for the lunch/after-work windows and for the
 * day boundary that daily quotas reset on (ITEM-03, COMM-07).
 */

export const KST_OFFSET_MINUTES = 9 * 60
const MINUTE = 60_000
const HOUR = 60 * MINUTE
const DAY = 24 * HOUR

export const ms = { minute: MINUTE, hour: HOUR, day: DAY } as const

export function now(): Date {
  return new Date()
}

export function plus(base: Date, amountMs: number): Date {
  return new Date(base.getTime() + amountMs)
}

export function minutes(n: number): number {
  return n * MINUTE
}

export function hours(n: number): number {
  return n * HOUR
}

export function days(n: number): number {
  return n * DAY
}

/** Wall-clock parts in Korea for a given instant. */
export function kstParts(at: Date): { y: number; m: number; d: number; hh: number; mm: number } {
  const shifted = new Date(at.getTime() + KST_OFFSET_MINUTES * MINUTE)
  return {
    y: shifted.getUTCFullYear(),
    m: shifted.getUTCMonth() + 1,
    d: shifted.getUTCDate(),
    hh: shifted.getUTCHours(),
    mm: shifted.getUTCMinutes(),
  }
}

/** Start of the Korean calendar day containing `at`, as a UTC instant. */
export function kstDayStart(at: Date): Date {
  const p = kstParts(at)
  return new Date(Date.UTC(p.y, p.m - 1, p.d) - KST_OFFSET_MINUTES * MINUTE)
}

/** `YYYY-MM-DD` in Korean local time, used as a daily quota window key. */
export function kstDateKey(at: Date): string {
  const p = kstParts(at)
  return `${p.y}-${String(p.m).padStart(2, '0')}-${String(p.d).padStart(2, '0')}`
}

/** Start of the minute containing `at`, used as a per-minute quota window. */
export function minuteStart(at: Date): Date {
  return new Date(Math.floor(at.getTime() / MINUTE) * MINUTE)
}

/** True when two half-open intervals overlap (ITEM-05). */
export function overlaps(aStart: Date, aEnd: Date, bStart: Date, bEnd: Date): boolean {
  return aStart.getTime() < bEnd.getTime() && bStart.getTime() < aEnd.getTime()
}

/**
 * Resolves an `HH:MM` policy window (e.g. lunch 11:30-14:00) to an absolute
 * UTC interval on the Korean day containing `reference`.
 */
export function kstWindowOn(reference: Date, from: string, to: string): { start: Date; end: Date } {
  const dayStart = kstDayStart(reference)
  return {
    start: plus(dayStart, parseClock(from)),
    end: plus(dayStart, parseClock(to)),
  }
}

function parseClock(value: string): number {
  const [h = '0', m = '0'] = value.split(':')
  const hh = Math.min(Math.max(Number.parseInt(h, 10) || 0, 0), 47)
  const mm = Math.min(Math.max(Number.parseInt(m, 10) || 0, 0), 59)
  return hh * HOUR + mm * MINUTE
}

/** Human Korean date-time for notification text and admin lists. */
export function formatKst(at: Date): string {
  const p = kstParts(at)
  return `${p.y}.${String(p.m).padStart(2, '0')}.${String(p.d).padStart(2, '0')} ` +
    `${String(p.hh).padStart(2, '0')}:${String(p.mm).padStart(2, '0')}`
}

/**
 * Exponential backoff with jitter for job retries (JOB-03).
 *
 * The jitter is applied before the cap, not after: jittering a capped value
 * can land above the cap, which makes the cap something other than a cap.
 */
export function backoffMs(attempt: number, baseMs = 30_000, capMs = 6 * HOUR): number {
  const exponential = baseMs * 2 ** Math.max(attempt - 1, 0)
  const jittered = exponential * (0.75 + Math.random() * 0.5)
  return Math.floor(Math.min(jittered, capMs))
}

/** A SQL date (parsed by the driver into a Date at UTC midnight) as YYYY-MM-DD; null stays null. */
export function isoDay(value: unknown): string | null {
  if (value === null || value === undefined) return null
  if (value instanceof Date) return Number.isNaN(value.getTime()) ? null : value.toISOString().slice(0, 10)
  return String(value).slice(0, 10)
}
