describe('permissions', () => {
  it('the catalogue in code is the one the database seeds', () => {
    const sql = readFileSync(path.join(root, 'db/migrations/0002_org.sql'), 'utf8')
    const seeded = [...sql.matchAll(/\('([a-z]+\.[a-z]+)',\s+'[^']+',\s+'[^']+',\s+'[^']*',\s+(true|false),/g)].map((m) => [m[1], m[2] === 'true'])
