  })

  const member = (perms: MemberContext['perms'], deptIds: string[] = ['d1', 'd2']): MemberContext => ({
    companyId: 'c', companyCode: 'acme', companyName: 'A', companyStatus: 'active', settings: {},
    memberId: 'me', displayName: '나', departmentId: 'd1', deptIds, roles: [], perms,
  })

  it('scope covers: self, department subtree, company', () => {
    expect(covers(member({ 'crm.write': 'self' }), 'crm.write', 'me', 'x')).toBe(true)
