        if (text.length < min) return fail(errors, path, `${eun(opts.label)} ${min}자 이상이어야 합니다.`)
        if (text.length > opts.max) return fail(errors, path, `${eun(opts.label)} ${opts.max}자 이하여야 합니다.`)
