  /** ISO-8601 instant; returns a Date. */
  instant(opts: { label: string }): Validator<Date> {
    return {
      run(value, path, errors) {
        if (typeof value !== 'string') return fail(errors, path, `${opts.label} 시각을 입력해 주세요.`)
        const d = new Date(value)
        if (Number.isNaN(d.getTime())) return fail(errors, path, `${opts.label} 시각 형식이 올바르지 않습니다.`)
        return d
      },
    }
  },

  oneOf<const T extends readonly string[]>(values: T, opts: { label: string }): Validator<T[number]> {
    return {
      run(value, path, errors) {
        if (typeof value !== 'string' || !values.includes(value)) {
          return fail(
            errors,
            path,
            values.length <= 6
              ? `${eun(opts.label)} ${values.join(', ')} 중 하나여야 합니다.`
              : `${opts.label} 값이 목록에 없습니다.`,
