  array<T>(item: Validator<T>, opts: { min?: number; max: number; label: string }): Validator<T[]> {
    const min = opts.min ?? 0
    return {
      run(value, path, errors) {
        if (!Array.isArray(value)) return fail(errors, path, `${opts.label} 목록 형식이 올바르지 않습니다.`)
        if (value.length < min) return fail(errors, path, `${eun(opts.label)} ${min}개 이상이어야 합니다.`)
        if (value.length > opts.max) return fail(errors, path, `${eun(opts.label)} ${opts.max}개 이하여야 합니다.`)
        const out: T[] = []
        value.forEach((entry, index) => {
          const parsed = item.run(entry, `${path}[${index}]`, errors)
          if (parsed !== undefined) out.push(parsed)
        })
        return out
      },
    }
