/** ?from=&to= (days), defaulting to this month so far. */
function period(ctx: Ctx): { from: string; to: string } {
  const t = today()
  const from = parseOne(v.day({ label: '시작' }), ctx.query.get('from') ?? `${t.slice(0, 7)}-01`, 'from')
  const to = parseOne(v.day({ label: '끝' }), ctx.query.get('to') ?? t, 'to')
  if (to < from) throw invalid({ to: '끝은 시작보다 같거나 늦어야 합니다.' })
  return { from, to }
}

