import { Fragment, type ReactNode } from 'react'

function safeHref(href: string): { href: string; external: boolean } | null {
  const h = href.trim()
  if (/^\/(?!\/)/.test(h)) return { href: h, external: false }
  try {
    const u = new URL(h)
    if (u.protocol === 'https:' || u.protocol === 'http:') return { href: u.toString(), external: true }
  } catch {
    /* 링크로 만들지 않는다 */
  }
  return null
}

function inline(text: string, keyBase: string): ReactNode[] {
  const out: ReactNode[] = []
  const re = /(`[^`]+`)|(\*\*[^*]+\*\*)|(\[[^\]]+\]\([^)\s]+\))/g
  let last = 0
  let m: RegExpExecArray | null
  let i = 0
  while ((m = re.exec(text))) {
    if (m.index > last) out.push(text.slice(last, m.index))
    const tok = m[0]
    const key = `${keyBase}-${i++}`
    if (tok.startsWith('`')) out.push(<code key={key}>{tok.slice(1, -1)}</code>)
    else if (tok.startsWith('**')) out.push(<strong key={key}>{tok.slice(2, -2)}</strong>)
    else {
      const lm = /^\[([^\]]+)\]\(([^)\s]+)\)$/.exec(tok)!
      const link = safeHref(lm[2]!)
      out.push(
        link ? (
          <a key={key} href={link.href} {...(link.external ? { target: '_blank', rel: 'noopener noreferrer nofollow' } : {})}>
            {lm[1]}
          </a>
        ) : (
          <span key={key}>{lm[1]}</span>
        ),
      )
    }
    last = m.index + tok.length
  }
  if (last < text.length) out.push(text.slice(last))
  return out
}

function splitRow(line: string): string[] {
  const t = line.trim().replace(/^\|/, '').replace(/\|$/, '')
  const cells: string[] = []
  let cur = ''
  for (let i = 0; i < t.length; i++) {
    if (t[i] === '\\' && t[i + 1] === '|') {
      cur += '|'
      i++
    } else if (t[i] === '|') {
      cells.push(cur.trim())
      cur = ''
    } else cur += t[i]
  }
  cells.push(cur.trim())
  return cells
}

